@startuml

class Game {
  + ID : string
}

class Player {
  + ID : string
}

class Deck {
  + ID : string
}

class Card {
  + ID : string
  + compareHeight(Card) : string
}

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

class ScoringTable {
  + ID : string
}

class Round {
  + ID : string
  + pointValue : int
}

class JackRound {}

class SoloRound {
  + soloType : string
}

class MandatorySoloRound extends SoloRound {}

class SoloType {
  TRUMP
  JACK
  QUEEN
}

Game "1" -- "4" Player : has
Game "1" -- "1" Deck : has
Game "1" -- "1" ScoringTable : has
Deck "1" -- "0..48" Card : contains
ScoringTable "1" -- "*" Round : consists of
Round "1" -- "*" Player : winning players
Round "0..1" -- "1" JackRound : is a
Round "0..1" -- "1" SoloRound : is a
SoloRound "1" -- "1" Player : solo player
SoloRound "1" -- "1" SoloType : has

@enduml

